"""Logotipo Decidiu para o cabeçalho e para a tela de login.

As imagens ficam embutidas aqui (base64), assim não dependem de arquivos separados nem da
pasta pública do Flet. Para trocar a marca, gere de novo com outra imagem (PNG).
"""
import flet as ft

COR_FUNDO_CABECALHO = "#FDFCF7"  # fundo creme do logotipo (a placa do cabeçalho usa a mesma cor)
COR_FUNDO_LOGIN = "#09233E"      # azul-marinho do logotipo (a placa do login usa a mesma cor)

LOGO_CABECALHO_B64 = (
    ""
)
LOGO_LOGIN_B64 = (
    ""
)


def marca_cabecalho(altura: int = 72) -> ft.Control:
    """Logotipo para o cabeçalho das telas (placa creme, proporção mantida)."""
    return ft.Container(
        bgcolor=COR_FUNDO_CABECALHO,
        border_radius=8,
        padding=6,
        content=ft.Image(src_base64=LOGO_CABECALHO_B64, height=altura),  # largura automática: mantém a proporção
    )


def marca_login(altura: int = 190) -> ft.Control:
    """Logotipo da tela de login (placa azul-marinho, proporção mantida)."""
    return ft.Container(
        bgcolor=COR_FUNDO_LOGIN,
        border_radius=12,
        padding=12,
        content=ft.Image(src_base64=LOGO_LOGIN_B64, height=altura),  # largura automática: mantém a proporção
    )
